		Color GetBackColor(string status)
		{
			switch (status)
			{
				case (Core.Constants.FlightScheduleStatus.Active):
				case (Core.Constants.FlightScheduleStatus.Arrived):
				case (Core.Constants.FlightScheduleStatus.Departed):
				case (Core.Constants.FlightScheduleStatus.Matched):
				case (Core.Constants.FlightScheduleStatus.PreArrival):
				case (Core.Constants.FlightScheduleStatus.PreDeparture):
					return Color.FromArgb(215, 255, 215);   // Green
				case (Core.Constants.FlightScheduleStatus.ArrivalDelay):
				case (Core.Constants.FlightScheduleStatus.DepartureDelay):
				case (Core.Constants.FlightScheduleStatus.Diversion):
				case (Core.Constants.FlightScheduleStatus.PartiallyMatched):
					return Color.FromArgb(255, 210, 166);   // Orange
				default:
					return Color.FromArgb(255, 215, 215);   // Red
			}
		}

